const axios = require('axios');
const fs = require('fs');
const path = require('path');

const projectId = process.env.PARAGON_PROJECT_ID;
const userToken = process.env.PARAGON_USER_TOKEN;

if (!projectId || !userToken) {
  console.error('Missing PARAGON_PROJECT_ID or PARAGON_USER_TOKEN');
  process.exit(1);
}

const url = `https://actionkit.useparagon.com/projects/${projectId}/actions`;

async function getSchema() {
  try {
    console.log(`Fetching schema for 'users' table from project ${projectId}...`);
    const response = await axios.post(
      url,
      {
        action: 'postgres:getSchema',
        parameters: {
          tableName: 'users'
        }
      },
      {
        headers: {
          Authorization: `Bearer ${userToken}`,
          'Content-Type': 'application/json'
        }
      }
    );

    const schema = response.data;
    const outputPath = '/home/user/paragon-postgres/schema.json';
    fs.writeFileSync(outputPath, JSON.stringify(schema, null, 2));
    console.log(`Schema saved to ${outputPath}`);
  } catch (error) {
    if (error.response && error.response.status === 400 && error.response.data.message && error.response.data.message.includes('Action not found')) {
        console.log('Action "postgres:getSchema" not found, trying "postgres:executeQuery" as fallback...');
        await executeQueryFallback();
    } else {
        console.error('Error fetching schema:', error.response ? JSON.stringify(error.response.data, null, 2) : error.message);
        process.exit(1);
    }
  }
}

async function executeQueryFallback() {
    try {
        const response = await axios.post(
            url,
            {
                action: 'postgres:executeQuery',
                parameters: {
                    query: "SELECT column_name, data_type, is_nullable FROM information_schema.columns WHERE table_name = 'users';"
                }
            },
            {
                headers: {
                    Authorization: `Bearer ${userToken}`,
                    'Content-Type': 'application/json'
                }
            }
        );

        const schema = response.data;
        const outputPath = '/home/user/paragon-postgres/schema.json';
        fs.writeFileSync(outputPath, JSON.stringify(schema, null, 2));
        console.log(`Schema (via executeQuery) saved to ${outputPath}`);
    } catch (error) {
        console.error('Error executing query:', error.response ? JSON.stringify(error.response.data, null, 2) : error.message);
        process.exit(1);
    }
}

getSchema();

